quests[33954] = { id = 33954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bloodmaul Scheme", description = "<This parchment contains crudely written notes detailing the Bloodmaul Clan's future plans.\n\nRogash will know what to do with this information.>", objectives = "Deliver the Ogre Plans to Rogash.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33955] = { id = 33955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing Pack", description = "Strange, I wonder where little Shivertail and his pack are? They normally show up for a feeding about now.\n\nI hope everything is alright.", completion = "You startle the small pup.", objectives = "Find Shivertail near Wor'gol in Frostfire Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33956] = { id = 33956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing Frostwolves", description = "{name}, I'm glad you're here.\n\nSeveral Frostwolf patrols have gone missing recently around the Bloodmaul Compound. Search the area around Bloodmaul and report back to me when you're done.", sourceObjective = "Search Bloodmaul for the missing Frostwolves.", sourceObjectiveStatus = "unverified-source-field" }
quests[33957] = { id = 33957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift for Raa'la", description = "I need to pack up this kill.  I promised my daughter Raa'la I would bring her home a gift from the hunt.\n\nThere are a couple baby Rylaks in the cave nearby. Maybe Raa'la would like one as a pet?\n\nWould you mind catching one while I finish up here?", objectives = "Collect a Baby Rylak for Raa'la in the Windswept Lowlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33958] = { id = 33958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Hollow", description = "I've learned that the Shadow Council is using the nearby deathweb spiders' venom to spread fel corruption and augment their forces after their defeat at the Burning Front.\n\nOne of my soulbinders saw a dreadlord headed into the eastern mines with Sha'tari, one of the remaining pieces of the Heart of Auchindoun.\n\nI need you to wrest Sha'tari from the dreadlord's quivering corpse and bring it to me, champion.", progress = "Did the demon have Sha'tari as we thought?", completion = "Just as I suspected. Thank you, {name}. With Sha'tari back in our possession there is only one piece of the Heart left to retrieve.", objectives = "Kill Xanatos the Defiler in Deathweb Hollow and retrieve Sha'tari.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33959] = { id = 33959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Sunk My Battleship!", description = "They sunk my battleship, {name}!\n\nI drove her in with a cargo of underwater explosives to place on the Iron Horde ships, but they spotted me and opened fire! Luckily I was able to salvage most of the explosives before she sank. Ain't nobody sinks my ship and gets away with it...nobody!\n\nTake the rest of the underwater charges and plant all of 'em on the western Battleship. You'll have to swim your way into the harbor to avoid detection.\n\nWhen you're done, swim into shore. I'll be waiting on the path!", objectives = "Plant the Underwater Explosives on the Iron Horde boats.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33960] = { id = 33960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talador Flowerpicker" }
