quests[33966] = { id = 33966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorgrond Flowerpicker" }
quests[33967] = { id = 33967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antivenin", description = "I'm worried about Nyami. She's so focused on retrieving the Heart of Auchindoun that she seems to have lost sight of everything else.\n\nI'm sorry, I'm not trying to belittle her wisdom, but look around! Every soldier we sent into the mine has been gravely injured by the deathweb spiders. Their wounds need immediate attention!\n\nPlease, can you retrieve some fangs from the spiders? I can use them to create an antivenin, but I need to stay here and keep them stable until then.", progress = "Do you have the fangs? We don't have much time!", completion = "Bless you, {name}. There have been enough innocent lives taken today.", objectives = "Collect 9 Deathweb Fangs in Deathweb Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33968] = { id = 33968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goren Boss Kill and Collect", description = "<Light bounces from within the gem creating rainbows on the nearby walls.>\n\nThis curious looking gem seems to have fallen from Pastrok's back. Perhaps a skilled gem-shaper or jewelcrafter would have a use for it." }
quests[33969] = { id = 33969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vile Defilers", description = "The spiders in the nearby overrun mine are feared by many, for their venom twists the very form of their victims. Many of the locals stay far away from their hollow, but I fear the Shadow Council has become privy to this information.\n\nOur scouts report that their warlocks are infusing these spiders with fel energy so that their venom turns their victims into demonic minions!\n\nWe must destroy the defiling crystals so this madness does not spread.", completion = "We were wise to not underestimate the threat of a land turned against us.", objectives = "Destroy 5 Defiling Crystals in Deathweb Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33970] = { id = 33970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Hollow", description = "I've learned that the Shadow Council is using the nearby deathweb spiders' venom to spread fel corruption and augment their forces after their defeat at the Burning Front.\n\nOne of my soulbinders saw a dreadlord headed into the eastern mines with Sha'tari, one of the remaining pieces of the Heart of Auchindoun.\n\nI need you to wrest Sha'tari from the dreadlord's quivering corpse and bring it to me, champion.", progress = "Did the foul demon have Sha'tari as we thought?", completion = "Just as I suspected. Thank you, {name}. With Sha'tari back in our possession there is only one piece of the Heart left to retrieve.", objectives = "Kill Xanatos the Defiler in Deathweb Hollow and retrieve Sha'tari.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33971] = { id = 33971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antivenin", description = "I'm worried about Nyami. She's so focused on retrieving the Heart of Auchindoun that she seems to have lost sight of everything else.\n\nI'm sorry, I'm not trying to belittle her wisdom, but look around! Every soldier we sent into the mine has been gravely injured by the deathweb spiders. Their wounds need immediate attention!\n\nPlease, can you retrieve some fangs from the spiders? I can use them to create an antivenin, but I need to stay here and keep them stable until then.", progress = "Do you have the fangs? We don't have much time!", completion = "Bless you, {name}. There have been enough innocent lives taken today.", objectives = "Collect 9 Deathweb Fangs in Deathweb Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33972] = { id = 33972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vile Defilers", description = "The deathweb spiders are remarkable creatures. Their venom twists the very form of their victims.\n\nWe are not the only ones privy to this information. The Shadow Council has already dispatched its warlocks to Deathweb Hollow to infuse the spiders with fel energy so that their venom turns creatures into demonic minions!\n\nWe must destroy the defiling crystals to prevent all of Talador from bending to Teron'gor's will!", progress = "The last thing we need is the monstrous creatures of this land joining the Legion's fold.", completion = "<Mehlar smiles.>\n\nIt would seem that the tide of this war is shifting in our favor.", objectives = "Destroy 5 Defiling Crystals in Deathweb Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33973] = { id = 33973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dying Wish", description = "I am too far gone to rescue, but thank you for speaking with me.\n\nBlademaster Bralok had his men starve and beat me, and he stole an heirloom that has been in my family since before we arrived on Draenor.\n\nShould you find it, please let me see it once more so I may die in peace.", progress = "The Blademaster must pay...", completion = "Thank you. Now that I know it is out of the hands of the Iron Horde, I can die peacefully.", objectives = "Recover Ahm's Heirloom from Blademaster Bralok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33974] = { id = 33974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dying Wish", description = "This appears to be an ancient Draenei heirloom. Blood stains on it would indicate that it was taken from its owner by force.\n\nAn inscription on the back says \"Ahm,\" which is likely its rightful owner.", objectives = "Speak to Ahm at Archenon Siegeyard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33975] = { id = 33975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Blasting Charges - Rubble A" }
quests[33976] = { id = 33976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Piece", description = "I am too injured to fight, {class}. I have failed my city and its people. This battle is yours.\n\nVorpil waits just ahead. He's trying to use Auch'naaru's powers for some sort of dark ritual.\n\nYou must do what I could not. Cut Vorpil down and retrieve Auch'naaru so the Heart of Auchindoun can be whole once more!", progress = "We need the final piece of the Heart!", completion = "Well done! I will take Auch'naaru to Auchindoun. The Shadow Council has no place in our lands.", objectives = "Take Auch'naaru from Vorpil Ribcleaver in Telmor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33977] = { id = 33977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessing of the Wolf" }
quests[33978] = { id = 33978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirit of the Wolf" }
quests[33979] = { id = 33979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buffeting Galefury" }
