quests[33987] = { id = 33987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Intro Tracking" }
quests[33988] = { id = 33988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion of the Soul Eaters", description = "<The note is scrawled hurriedly across the parchment.>\n\nTelmor is lost. The Shadow Council is dragging our fallen into piles and feeding the souls to their leader. There is blood on my hands...\n\nPlease, if anyone reads this message, burn the bodies of our fallen so our enemy cannot use them.\n\n- Restalaan, Captain of the Guard", objectives = "Use torches from a forge to burn 4 body piles in Telmor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
