quests[34004] = { id = 34004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hansel, Report", description = "I have Hansel directing our counter-fire against the Iron Horde's war machines.\n\nI need to know what's going on and why some of the orcs slipped through. He's down the hill to the north.", sourceObjective = "Speak with Hansel Heavyhands at Bastion Rise in Gorgrond.", sourceObjectiveStatus = "unverified-source-field" }
quests[34006] = { id = 34006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Build Us A Backdoor", description = "According to the prisoner here, the Stonemaul ogres are providing slaves and supplies to the Iron Horde. No creature should live a life in chains! And to add insult to injury, Orgrim Doomhammer is here to discuss terms with them!\n\nI sent my wolf Nightstalker ahead to find a weakness. If there is another way in, he will find it.\n\nGo, find my wolf near walls of the Stonemaul camp south of here. Test their defenses.\n\nIf you cannot find us a way in, then make one.", sourceObjective = "Help Nightstalker find a weak spot in the Stonemaul Slave Camp walls.", sourceObjectiveStatus = "unverified-source-field" }
quests[34008] = { id = 34008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Are Leaving!", description = "We have who we came for. Find the others. Tell them to get back to the caravan as soon as possible.\n\nIt will not be long before the ogres figure out how few of us there actually are. We will wait for you at the front gates." }
quests[34012] = { id = 34012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Need More Teeth", description = "<Prowler Sasha silently holds out his hand to reveal a necklace crafted of stained leather and putrid brown ogre teeth. All have a matching tone of rot to them.>\n\n<It has several knots that appear to be missing additional teeth.>", progress = "<Prowler Sasha stares at you with cold, merciless eyes.>", completion = "<Prowler Sasha nods and assembles two necklaces.>", objectives = "Collect 30 Putrid Brown Ogre Teeth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34013] = { id = 34013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Never Forget", description = "We had to escape Telmor with what few we could save.\n\nSomeone disabled Leafshadow's cloaking field; I know not who, but I suspect it had to have been one of our own.\n\nWe will retrieve our livelihoods in time, but we cannot risk losing our sacred artifacts.\n\nIf you are able, bring Leafshadow, our town registry, and our prayerbook to safety.", progress = "Some things are worth fighting for, {race}. These are such things.", completion = "With these, we can account for our fallen and rebuild. We will persevere.", objectives = "Recover the Telmor Registry, the Auchenai Prayerbook, and Leafshadow in Telmor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34019] = { id = 34019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadows Awaken", description = "We've managed to pin Ner'zhul inside the Observatory, but he's taken many down with him.\n\nHe has taken Yrel's sister, Samaara.\n\nI am needed to hold the line here. Please, do whatever you can to save her, hero.", progress = "The Shadowmoon clan's aggression began when the Iron Horde arrived on Draenor.", completion = "Your aid in retaking Teluuna Observatory has not gone unnoticed, hero. I grow increasingly impressed at your prowess in battle.\n\nPerhaps you could share some of your knowledge with my disciples. They could learn much from a seasoned adventurer such as yourself.\n\nI have something for you, as a thanks for what you've done even in the short time you've been here. Perhaps it will help you get this garrison of yours on its feet.", objectives = "Confront Ner'zhul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34024] = { id = 34024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fungal Heart", description = "The second ingredient I will need for the elixir is harder to obtain.\n\nAlong the river roam Marsh Giants - fungal monstrosities whose hunger is never sated. I will need three of their hearts.\n\nThe stronger the heart, the more potent the mixture, and the clearer my vision.", objectives = "Collect 3 Fungal Hearts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34025] = { id = 34025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nuke Bastion Rise Tracking Flag" }
quests[34026] = { id = 34026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Campaign: Seismic Matters", description = "One of our junior surveyors has been harassing me about unusual seismic activity. I find it hard to believe that we accidentally built on some kind of fault line - we triple checked!\n\nCan you have a word with him?", completion = "Ach! Sir {name}, ye've arrived just in time!", objectives = "Speak with Jr. Surveyor Dorn at your garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34027] = { id = 34027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Groundbreaking Data", description = "Aye, we triple-checked the site before we set up here. Nary a peep from the ol' earthly deep.\n\nBut there's been rumblin's today, and they're gettin' closer! I tell ya somethin' ain't right!\n\nYe don't have to take my word for it - the Tremor-Tracker is just about finished collecting data. Check it out an' see fer yerself!", progress = "Go on, check out the Tremor-Tracker! It ain't gonna bite ye.", completion = "I KNEW somethin' was wrong! IN YER FACE, Alexston!\n\nAh, excuse me.\n\nNow, where have I seen machines like this before?\n\nOh yeah! The Dark Iron!", objectives = "Use the Tremor-Tracker in your garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34028] = { id = 34028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "These Look Familiar...", description = "So what is the Iron Horde doing with Dark Iron technology? I know who ta ask!\n\nThaelin Darkanvil is a genius engineer from the Dark Iron clan who's been helping us here on Draenor. You may have already met him in yer travels, eh?\n\nWord is he set up a bunker somewhere in Gorgrond, a secret workshop so-to-speak. If ye can find him, he may know somethin' about this.\n\nEr, and be cautious, eh? The Dark Iron may be our allies now, but I trust 'em about as far as I can throw 'em.", completion = "Mmf! Mm- mff!!\n\n<You remove his gag.>\n\nTHEY GOT THAELIN!!", objectives = "Find Thaelin's Workshop in Gorgrond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34029] = { id = 34029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Prototype", description = "A few days ago a bunch of Iron Horde orcs showed up and kidnapped Thaelin. They've been keeping me alive as collateral to make sure he cooperates.\n\nI don't know where they took him, but I know how to get us there.\n\nThaelin keeps a tracking device on him at all times - don't ask where he hides it. Anything he makes that can move has a \"Come to Papa\" button that sends it straight to him.\n\nIn retrospect, not a great feature for the walking bombs... but perfect for the mole machine! Jump in and let's go!", completion = "Close enough!", objectives = "Use the Prototype Mole Machine to look for Thaelin Darkanvil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34030] = { id = 34030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captive Engineer", completion = "{name}! Oh, yer a sight for sore eyes!\n\nThe prototype mole machine was able to track me here all the way from the shop? I even impress myself sometimes.\n\nNow that I know Hansel is safe, I can enact the brilliant escape plan I've been working on. Glad to have ye here for this!", objectives = "Find Thaelin Darkanvil in the Iron Siegeworks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34031] = { id = 34031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something to Remember Me By", description = "The Iron Horde want my inventions so bad? Then we'll leave some behind.\n\nThese little beauties will blow the treads clear off a tank AND melt her chassis into the dirt. Let's see them try and drive their shoddy cannons out of this place!", progress = "Don't be shy with those mines, I got plenty.", completion = "For the record, the mines don't have any voice commands.\n\nI learned that lesson awhile back...", objectives = "Place 4 Dark Iron Mines in the Iron Siegeworks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34032] = { id = 34032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Privileged Information", description = "I'm not the only prize the Iron Horde brought back after raiding my workshop.\n\nOverlord Blackhammer, the maniac in charge of this operation, took my notebook as his own personal treasure.\n\nManufacturing techniques; schematics for new inventions; embarrassing doodles.\n\nIt's got all my secrets!\n\nCan I count on you to help me get it back?", progress = "That book has my working notes from the last five years. It's too dangerous to leave behind!", completion = "Aye, there she is.\n\nThank you, {name}. Let's get out of here, shall we?", objectives = "Loot Thaelin's Notebook from Overlord Blackhammer in the Iron Siegeworks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34033] = { id = 34033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "And The Mole You Rode In On", description = "I think we've kept Hansel waiting long enough. Can you take me to him? Then we can all hitch a ride out of here on the mole machine.", completion = "So I guess it's safe to say my old workshop is compromised. We'll have to find a new place to set up shop...", objectives = "Bring Thaelin Darkanvil to Hansel Heavyhands in the Iron Siegeworks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34034] = { id = 34034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Campaign: Grinding Gears", description = "Commanda! Da Frostwolf orcs at Thunder Pass have reported a horrible grinding noise boomin' tru da canyon. We suspect it's some kind of Iron Horde war machine.\n\nGazlowe has agreed ta investigate, but he be wantin' a cash bonus. Goblins! Meet wit him at Thunder Pass and deliver dis payment.", progress = "Yo! You got the dough?", completion = "<Gazlowe's face brightens as you hand over the bulging bag of coins.>\n\nHeyyy! Now we're talking!\n\nI usually prefer not to get my hands dirty, but for that kind of cash you could get me to field-strip a kor'kron outhouse.\n\nGlad to have some muscle here to back me up - and since I'm such a nice guy, here's a little somethin' for your troubles.", objectives = "Deliver Gazlowe's Payment to Gazlowe near Thunder Pass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34035] = { id = 34035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Know The Drill!", description = "It's a machine alright. A drill - a BIG one! Fortunately, we don't have to take apart the whole thing.\n\nThey're relying on forced induction, using twin superchargers to pipe extra boost into the engine. Without that boost, the drill is useless.\n\nGet in there and open the clutch on the back of the drill. That'll draw some attention away from the turbines.\n\nI'll take care of the turbines - you just worry about the hordes of bloodthirsty orcs.", progress = "You ready to roll?", completion = "Ya know... this thing is actually pretty impressive.\n\nThe drive system seems... familiar...", objectives = "Help Gazlowe sabotage the Iron Stonegrinder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34039] = { id = 34039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Overlord Blackhammer", description = "So, we COULD just leave now. We got what we came for, and I even did a little charity work to help Thaelin escape.\n\nBut there's also this.\n\n<Gazlowe holds up a scrap of paper showing a hand-drawn depiction of an especially mean looking orc.>\n\nIt's an SI:7 bounty for one Overlord Blackhammer, who just happens to operate out of this very facility. You help me take him out, I pay you. Then I take his head to the Alliance and collect on the bounty. Everyone wins!\n\nWell, everyone except for Blackhammer.", progress = "You aren't getting cold feet on me now, are ya?", completion = "<Gazlowe fishes around in his pouch before producing a single gold piece.>\n\nErr... looks like I'm a little short. Personal bodyguard fees really add up!\n\nI'll give you a proper cut when we get back to your garrison. Come on, you know I'm good for it!", objectives = "Slay Overlord Blackhammer in the Iron Siegeworks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34040] = { id = 34040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maker's Mark", description = "I don't get it - most of the Iron Horde junk is about as advanced as strapping cannons to a gronn. Even the drill itself is nothing special. But that induction system was a work of art...\n\nThis don't add up at all!\n\nDespite my better judgment, I gotta find out who made this. I wanna look at more of what they got in the Iron Siegeworks, see if anything's been signed.\n\n<Gazlowe pats the sack of coins on his belt.>\n\nWhaddaya say? Wanna be my bodyguard?", progress = "You get paid when we get out of this place alive.", completion = "That's Darkanvil's signature! I knew I'd seen that work somewhere before.\n\nThaelin Darkanvil is a Dark Iron dwarf who came to Draenor with the Alliance forces, and a damn brilliant engineer. We have what you might call a friendly rivalry.\n\nBut why's Thaelin making weapons for the Iron Horde?", objectives = "Inspect 5 Siege Parts in the Iron Siegeworks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34041] = { id = 34041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Four Finger Discount", description = "I gotta admit, establishing a supply chain to a primal world on the wrong side of time is tough, even for me. Gotta make due with, uh... \"locally sourced\" goods.\n\nSay what you want about the Iron Horde, but when it comes to raw materials, they got connections!\n\nKeep an eye out for some of the more valuable goods in the Iron Siegeworks. I packed a few rocket chickens we can use to send the good stuff back to your garrison.", completion = "Not a bad haul. Here's yer cut!", objectives = "Steal a Blackrock Cog, Condensed Geyser Gas, and a Carbonfrost Flamecore from the Iron Siegeworks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34042] = { id = 34042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fellow Gearhead", progress = "You gotta respect your fellow gearheads!\n\nPlus, I made a TON of money copying those walking bombs he designed.\n\nEr... you didn't hear that last part.", completion = "Don't worry, Thaelin can handle himself. That was my good deed for the year - don't tell nobody!\n\nHey... you think I can write off that fuel as a business expense?", objectives = "Find Thaelin Darkanvil in the Iron Siegeworks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34043] = { id = 34043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkest Night", description = "This keystone will grant its bearer entry into Anguish Fortress.\n\nTake it and meet Prophet Velen outside the Shadowmoon fortress.\n\nHe intends to face Ner'zhul head-on.", completion = "Good, you've arrived. Rulkan's message said that you would not be long.", objectives = "Speak to Prophet Velen at Anguish Fortress.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34047] = { id = 34047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tuurem Explosion Tracker" }
quests[34048] = { id = 34048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Mole Machine, Go Home\"", description = "My patented \"Come to Papa\" voice command was only the first step.\n\nI also programmed all of my mole machines with a \"Go Home\" command that'll send 'em auto-diggin' to a pre-determined location - my workshop in Gorgrond!\n\nLet's send the mole machines home before the orcs stink 'em all up with their stupid breath and their sweaty... leather... thongs.\n\n<You hear Thaelin gagging a little from inside The Suit.>\n\nBlech!", progress = "If the voice command fails, you can always try the manual override.\n\nYe simply hold down the control pedal, shift into reverse, and pull the escape lever at the same time.", completion = "There, my beauties are safely out of the hands of the Iron Horde. No more orcs poppin' out of the ground!\n\nThere's just one more thing I need to do before I can leave with a clear conscience.", objectives = "Send 5 Mole Machines home from the Iron Siegeworks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34053] = { id = 34053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SoL Conversation Tracker" }
quests[34054] = { id = 34054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Side of the Moon", description = "<Prophet Velen's voice continues.>\n\nYrel and I have located Warlord Ner'zhul. He is meeting with Grommash Hellscream atop the highest altar overlooking Anguish Fortress.\n\nMeet us there. We must stop him.", progress = "Ner'zhul will pay for what he has done.", completion = "We saved everyone we could, {name}. We were too late for the others... including my sister.\n\nProphet Velen is right. When it is asked of us, we ALL must fight. I promise this: I will never again let my loved ones suffer.\n\nNer'zhul is close to calling down the Dark Star. We are the only ones who can stop him.", objectives = "Find Ner'zhul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34055] = { id = 34055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Origin Unknown", description = "For my first field assignment, I would say I'm doing quite well!\n\nI've discovered a strange portal in this cave that has unleashed a number of equally strange void creatures, and there's no clear reason why! Fascinating, isn't it?\n\nScientific inquiry aside, these things may be benign right now, but at the rate they're pulling energy in that won't last long.\n\nI need you to take them out, send their essences back to... wherever it is they came from, and shut down that portal!", objectives = "Slay 4 Voidborne Errants in Waning Crescent. Afterwards, shut down the portal in Waning Crescent.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34059] = { id = 34059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keeping Calm", description = "My husband, one of our shaman, went to the ritual cave just below the village to seek the advice of our ancestors.\n\nJust before you arrived I heard sounds of fighting coming up from there. I fear that one of Ner'zhul's agents has attacked him!\n\nPlease, will you go find him and return him home safely?", objectives = "Find Kaduz in the Cave of Spirits below Palemoon Village and rescue him from Ner'zhul's agent.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34060] = { id = 34060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krasarang RRP - Daily Vignette - Rogue Boss" }
quests[34061] = { id = 34061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krasarang RRP - Daily Vignette - Priest Boss" }
quests[34062] = { id = 34062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krasarang RRP - Daily Vignette - Warrior Boss" }
quests[34063] = { id = 34063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemies Above", description = "We have dealt a crushing blow to the Thunderlords with the death of the Iron Wolf {name}, but we can not rest yet.\n\nThe Thunderlord generals will be fighting like caged wolves to maintain their place in the Iron Horde and that means bad news for us.\n\nI sent Scout Ruk'gan to keep an eye on their movements but he hasn't reported back for some time now. If you would help us then seek out Ruk'gan. \n\n Lok'tar {name}!", sourceObjective = "Speak with Scout Ruk'gan near the Bones of Agurak.", sourceObjectiveStatus = "unverified-source-field" }
quests[34064] = { id = 34064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Search For Drogguk", description = "Drogguk has taken it upon himself to watch the Iron Horde's movement to ensure they do not find our village.\n\nIt has been two days and he has not yet returned. If you are willing, I would ask that you seek him out and bring him home. His family worries.\n\nHe tends to make his post roughly southeast of here.", objectives = "Find Drogguk in the Iron March.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34066] = { id = 34066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Savage Vengeance", description = "The Thunderlord are a blight {name}.\n\n<Ruk'gan spits in disgust.>\n\nMy daughter, Grishna, was killed by those monsters. Only their blood will bring me peace now.\n\nIf you would help me then I need you to cause a distraction so I can sneak to a position closer to their camp.\n\nKilling a few of their so called \"Iron Thunderguard\" would be perfect.", completion = "You have done well, {class}.\n\nNow before we can continue our assault we need to look for any supplies in the area that could help our fight.", objectives = "Kill 10 Iron Thunderguards within the Bones of Agurak in Frostfire Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34067] = { id = 34067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Collection of Coils", description = "This coil of rope has been woven thick, the better for the Thunderlord Wranglers to handle the dangerous beasts they tame.\n\nScout Ruk'gan might have a use for this and a few more like it.", progress = "I'm growing tired of waiting, do you have anything to help our assault or not?", completion = "Rope? Do you expect me to tie a noose and ask the Thunderlords to go hang themselves?\n\nWait... that gives me an idea. Yea, I think I can make this work with the right materials.\n\nGood Job.", objectives = "Gather 5 Coils of Sturdy Rope from Thunderlord Wranglers in the Bones of Agurak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34068] = { id = 34068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Rockhoof" }
quests[34069] = { id = 34069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getting the Points", description = "The Thunderlord Spear is extremely light and strong.\n\nScout Ruk'gan might be able to use this and a few more like it.", progress = "What is it {class}? Have you got something for me?", completion = "Hrm, yes these spears look pretty good.\n\nNot bad! I know just what to use these for!", objectives = "Gather 5 Thunderlord Spears within the Bones of Agurak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34070] = { id = 34070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "At the End of Your Rope", description = "With the spears and rope you gathered the Thunderlord Sky Riders will no longer be out of our reach. Even they will feel our wrath!\n\nI've tied the rope to the spears you brought me to fashion a harpoon. Hunt the Sky Riders that are flying all over the valley. Take the Harpoon and throw it at them as they circle by. If your aim is true the barbs should allow the spear a firm hold allowing you to yank the rider right towards you!\n\nIf your aim is bad... well... try not to miss.", completion = "Well done {name}! The removal of the Sky Riders takes the heat off us for a bit. Keep your weapon in hand though, we're not done with them yet.", objectives = "Use the Barbed Harpoon to unseat and kill 5 Thunderlord Sky Riders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34072] = { id = 34072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tar Get of Opportunity", description = "General Vul'gath leads this band of Thunderlord. He is a coward and hides in his hut, yelling orders at his warriors through the walls.\n\nWe will need to show him that his flimsy defenses can not stand against the Frostwolves!\n\nI'll need some tar to carry this out. There are a couple of tar pits to the south, go gather a few globs from the oozes that reside there and bring them to me.", progress = "We need that tar soon {name}! Get to it!", completion = "Ugh, those smell awful! No, I don't need to see them. I'll take you at your word that you have them all.\n\nLet's get a move on before another Thunderlord patrol stumbles upon me.", objectives = "Gather 5 Globs of Sticky Tar from the Black Tar's in the Bones of Agurak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34073] = { id = 34073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burn Them Down", description = "Now, we begin our assault, {name}!\n\nGet down to Agurak's Fall and use these tarbombs to destroy their rylak egg incubators.\n\nWhile you are busy I will sneak down into their camp and prepare for the next phase of our attack. Meet me there once you have burned everything.", completion = "Good job {name}, I was able to use the commotion from your work to sneak into the camp.\n\nNow we have only one thing left to do.", objectives = "Burn down the Thunderlord Rylak Incubators within Agurak's Fall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34074] = { id = 34074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Iron March" }
quests[34075] = { id = 34075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vul'gath's End", description = "Vul'gath's time has come to an end, {name}. My daughter's blood is upon his hands, now his blood will be on ours!\n\nShow no mercy and strike him down!", completion = "Thank you,{name}.\n\nI wish we could bring him back just to kill him again but I guess this will suffice.\n\nI hope the spirit of my little one will now know peace.", objectives = "Kill General Vul'gath within Agurak's Fall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34076] = { id = 34076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Burial Fields" }
quests[34077] = { id = 34077, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble to the South", description = "A group of Alliance soldiers headed south from here not long ago. They said they were searching for some sort of special flower.\n\nTo be frank, I'm concerned for their safety. This area is still crawling with Iron Horde.\n\nThey could surely use your help if you're able. Follow the road south and you should find their position.", sourceObjective = "Find Captain Renault south of Pilgrim's Sojourn in Shadowmoon Valley.", sourceObjectiveStatus = "unverified-source-field" }
quests[34078] = { id = 34078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Payment Due for Services Rendered", description = "I'm ready to get outta here, and I ain't hoofin' it back through all those orcs.\n\nFortunately, I kept a few extra rocket chickens to get us back to your garrison in style! Let's get up to the roof and find a decent place to take off.", completion = "Told you I was good for it!", objectives = "Bring Gazlowe to the roof of Overlord Blackhammer's fortress in the Iron Siegeworks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34079] = { id = 34079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission Successful", description = "The Thunderlords are finished {name} and our job is complete. I'll stay here and watch over the area.\n\nYou should head back to Sergeant Gil'nath. I'm certain he will have another task for you.", sourceObjective = "Speak to Sergeant Gil'nath in Frostfire Ridge.", sourceObjectiveStatus = "unverified-source-field" }
quests[34080] = { id = 34080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return To Sender", description = "This tiny tracking device is used to collect biological data. It appears to have been fastened to a dart and fired from long range.\n\nAfter closely examining the device, you are able to trace the signal to a receiver nearby. The information contained within could be important; it's probably a good idea to find the owner and return it.", objectives = "Return the Subdermal Tracking Device.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34083] = { id = 34083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[34084] = { id = 34084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keeping Calm", description = "<These beads must belong to Kaduz, the shaman you rescued. They are engraved with the name \"Dulga\".>\n\n<He said to meet him in nearby Palemoon Village. You will surely find both Kaduz and Dulga there.>", sourceObjective = "Speak to Dulga in Palemoon Village.", sourceObjectiveStatus = "unverified-source-field" }
quests[34087] = { id = 34087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through the Looking Glass", description = "An ally of yours, Thaelin, is helping us counter the Iron Horde.\n\nHe claims this device can be used to spy on the enemy, even so far as hearing what they are saying at great distance.\n\nI do not trust such devices. Use it and let me know what you see.", progress = "Take a look through Thaelin's Observicopter. I don't trust that machine.", completion = "Orgrim leads the Iron Horde in Talador... Now we know the face of our enemy.", objectives = "Look through Thaelin's Observicopter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34088] = { id = 34088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Too Many Irons in the Fire", description = "We must slay the Iron Horde troops who infest our lands.\n\nFind those who would sully our great forest and show them the hand of justice.", completion = "The Iron Horde has no consideration for the wonders of the forest. In death, they will know respect.", objectives = "Kill 15 Iron Horde at Mor'gran Logworks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34089] = { id = 34089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Short Supply", description = "The Iron Horde has explosive devices stored throughout the heart of their logging camp.\n\nWe must recover them so they are not used against us.\n\nI will keep an eye on Maraad... I worry for him in his anger.", progress = "Have you found the Iron Horde Explosives yet?", completion = "I believe we can use these explosives against the Iron Horde.", objectives = "Collect 6 Iron Horde Explosives.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34090] = { id = 34090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thaelin's Quick Fix", description = "Those orcs sure like to pile things up in one place. That gave me an idea...\n\nI've built this ingenious device for ya! When you get near a target, it'll let you know, and you can deploy it for a big, satisfying, kerBOOM!", progress = "BOOM! Ahahahahaaa!", completion = "Nothing like a good explosion to warm the heart.", objectives = "Destroy the Thunderlord Cache, Blackrock Forge, and Log Storage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34091] = { id = 34091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decommissioned Mission", description = "Ketya Shrediron,\n\nYour new Iron Shredders are a menace to our own soldiers.\n\nDecommission the prototype and store it out of the way until you've worked out the kinks.\n\nI will send Engineer Trak to work on it in the meantime.\n\n- Orgrim Doomhammer", completion = "A prototype Iron Shredder, huh?! I bet we can get this thing working... they didn't have Thaelin Darkanvil to fix it!", objectives = "Kill Engineer Trak and recover the Decommissioned Iron Shredder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34092] = { id = 34092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desperate Measures", description = "We've identified the location of Teron'gor's compound, but his forces are already far stronger than anything we've ever faced. We need to gain an edge, and quickly.\n\nThe cursed spirits of the Ango'rosh ogres, our ancient enemies, linger in nearby ruins. Go there and gather the Ango'rosh Spellbook and the Grimoire of Binding.\n\nPerform the ritual described within at their altar to lift their curse and seek their aid.\n\nIt's a long shot, but we don't have any other options.", progress = "Were you able to acquire the aid of the Ango'rosh?", completion = "You radiate the power of the Ango'rosh!\n\n<Restalaan smiles.>\n\nIt is time to take this battle to Teron'gor's doorstep.", objectives = "Gather the Ango'rosh Spellbook and the Grimoire of Binding, then perform the ritual at the Altar of Ango'rosh in the Ango'rosh Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34093] = { id = 34093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getting the Points", description = "Those Thunderlords circling above us are a problem {name}.\n\nThey fly their pathetic Rylaks leisurely across the valley, thinking they are safe to rain spears down on our heads. We need to show them they are not safe from Frostwolf Vengeance!\n\nI have a plan but we will need to gather some material. Go hunt across the valley for any of their spears that survived intact. I think five should be enough.", progress = "What is it {name}? Have you got something for me?", completion = "Hrm, yes these spears look pretty good. Outstanding {name}! I know just what to use these for!", objectives = "Gather 5 Barbed Thunderlord Spears within the Bones of Agurak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34094] = { id = 34094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vol. X Pages ?", description = "That shredder had a manual jammed in the cockpit, but it's missing a lot o' pages. If we can find those manual pages, I'd bet my third toe I can get the prototype shredder working again.\n\nI coulda swore I saw a few of those pages floatin' about in  Archenon Siegeyard. Maybe the orcs there carry them.", progress = "Have you found those pages? These manuals are ridiculous.", completion = "I wondered why the manual was so big... they write with really big letters!", objectives = "Find 20 Manual Pages on orcs at Archenon Siegeyard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34095] = { id = 34095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iron Them Out", description = "The orcs themselves are not the only threat. They still have siege weapons of significant power.\n\nThey've already been used against Tuurem, and we must not allow for their continued operation.\n\nSabotage siege weapons using the explosives you collected from the logging camp.", completion = "They will be unable to use those weapons against us when we attack Tuurem.", objectives = "Destroy 6 Iron Horde Siege Engines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34096] = { id = 34096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Eye for a Spy", description = "I'll get the prototype shredder working right now!\n\nTake a look through my Observicopter. You'll see what you're about to head into...", progress = "Take a look!", completion = "That's a lot of orcs, eh? Glad I'm here tinkerin' away instead of in the thick of it.", objectives = "Look through Thaelin's Observicopter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34097] = { id = 34097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Born to Shred", description = "I've got this prototype shredder operating on most cylinders.\n\nBoy, will they be surprised when you stomp them with their own machine!\n\nCan't wait to watch you from the safety of the Observicopter.", completion = "-- ENEMIES ELIMINATED --", objectives = "Kill 100 Iron Horde in Tuurem using the Iron Shredder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34098] = { id = 34098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Engineering Her Demise", description = "-- THE MOTHER HAS BEEN DETECTED. WARNING! WARNING! --", completion = "The screams of our enemies washed over me. The people of Tuurem are avenged.", objectives = "Defeat Ketya Shrediron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34099] = { id = 34099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for Shattrath", description = "To stop the Iron Horde, we must overcome prejudice and work together, if only for this purpose.\n\nHorde, Alliance, past, present... all meaningless in the face of this enemy.\n\nWe will retake Shattrath together... or die trying.", completion = "Maraad is dead... but we must carry on. I will not let his sacrifice be for nothing.", objectives = "Repel the Iron Horde from Shattrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34101] = { id = 34101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Aruumel's Worn Mace" }
quests[34102] = { id = 34102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mark of Defiance", description = "As you look upon the Frostwolf banner you remember struggles that have led you and the Frostwolves to this point.\n\nRuk'gan has suffered in his battles with the Thunderlord and would appreciate an extra show of defiance. \n\nAs the banner rustles in the wind you're inspired to mark the foes of the Frostwolf with its standard.", progress = "Anything to report, {name}?", completion = "Good work,{name}!\n\nSeeing Frostwolf banners standing proudly over our crushed foes fills me with pride!\n\nLet them forever fear the wrath of the Frostwolves!", objectives = "Use the Battle-Worn Frostwolf Banner on the corpses of 6 Thunderlord Orcs in Agurak's Fall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34103] = { id = 34103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Kil'uun", description = "I have a bounty set on a bird, commander. Yes, a bird.\n\nThe issue is this thing is massive, and it was last sighted a stone's throw away from the Horde base to the south in the forest. The locals call it Kil'uun.\n\nIf you'd like to track the creature down and bring back its beak I wager it would fetch a sack or two of gold for your coffers!", progress = "Any luck tracking down that bird, commander?", completion = "I have no idea how you managed to track down the creature so close to the Horde base, but well done sir.", objectives = "Hunt Kil'uun and bring its beak to Patrick Messer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34104] = { id = 34104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Hilaani", progress = "Have you had time to kill Hilaani?", completion = "Thank you, commander! The peasants will be singing songs about your generosity tomorrow.", objectives = "Kill Hilaani and bring the Pile of Riverbeast Meat to Patrick Messer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34105] = { id = 34105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Ra'tok the Hammer", description = "I've got an issue that could use your assistance, commander.\n\nA few of our men spotted an Iron Horde lieutenant wandering in the cliffs near here. We suspect she's directing their forces to strategic ground as they land on the Orunai Coast.\n\nI would feel much better about the safety of this fort if you could take her out.", completion = "All hail your glory, commander.", objectives = "Dispatch Ra'tok the Hammer in the Orunai Coast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34106] = { id = 34106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Ra'tok the Hammer", description = "The Iron Horde have no honor. They disgust me.\n\nWe spotted one of their lieutenants wandering the cliffs not far from our base. I believe that she is tracking our movements to prepare for some sort of assault from the Orunai Coast.\n\nI understand you have much to do, commander. If you have the time, I believe it would be beneficial to our position's integrity.", completion = "I knew you'd kill her. No Iron Horde is safe from your wrath.", objectives = "Kill Ra'tok the Hammer in the Orunai Coast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34107] = { id = 34107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Hilaani", description = "We need more meat, commander.\n\nI know what you're thinking. What about all of that meat right behind me?\n\nThat's the problem. It'll be gone in a day if we're lucky.\n\nThere's a riverbeast that lives in the lake to the south. Locals call her Hilaani. Massive, lots of meat.\n\nIf you would take down the beast and bring me her meat, your wolves will be better off for it.", progress = "Good to see you, commander.", completion = "Is that what I think it is? You are too kind, commander!", objectives = "Slay Hilaani and bring a Pile of Riverbeast Meat to Beastmaster Tagh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34108] = { id = 34108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Kil'uun", description = "It's that damned bird!\n\nEvery few hours, this blasted thing flies right past here, and none of these idiots will stop it.\n\n\"It's got the crazy in its eyes,\" they tell me. Pah!\n\nCommander, this bird will be the end of me. If you see it, could you cut off its stupid head and give it to me?\n\nIt'd make me feel better.", progress = "If you decide to kill that creature, I will name my first-born in your honor.", completion = "Praise to {name}! For the Horde!", objectives = "Bring Kil'uun's Beak to Beastmaster Tagh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34110] = { id = 34110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Girl 1 Found" }
