quests[34154] = { id = 34154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destination: Unknown", description = "Teron'gor and Gul'dan were just leaving through the portal as I arrived... and I... I know I won't be able to defeat them.\n\nI'll hold open the portal as long as I can. It will be up to you to strike the killing blow.\n\nOur fate is in your hands, {name}.", completion = "Teron'gor and Gul'dan... they slaughtered everyone...\n\n...and then they just... disappeared... into the shadows...\n\nHow did they know where to go?", objectives = "Destroy Mongrethod in the Remains of Xandros.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34155] = { id = 34155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Gorgrond Treasure 06" }
quests[34157] = { id = 34157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Heart of Madness", description = "{name}, Nyami ran off to 'take down Teron'gor herself.'\n\nYou need to find her. She has no chance against him on her own.\n\nI must remain here and organize our ranks should another attack fall upon us. I'm counting on you.", completion = "You have to hurry... Teron'gor just left!", objectives = "Speak to Soulbinder Nyami at the Seat of Depravity in Gul'rok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
