quests[34181] = { id = 34181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mutation Station", description = "Grulk very weak...barely stand.\n\nGrulk not always look this way. Grulk once was orc...Iron Horde make Grulk mutant. Grulk angry at Iron Horde...so Iron Horde lock Grulk in cage...hurt Grulk.\n\nGrulk HATE Iron Horde...Grulk want SMASH them...make them PAY!\n\nTake serum...use on Grulk to make Grulk strong! Help Grulk SMASH Iron Horde!", objectives = "Assist Grulk in destroying the Mutation Lab by administering the Mutation Serum to him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
