quests[34209] = { id = 34209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vouchsafe Our Arrival", description = "A matter of great importance has arisen. While you were away, Archmage Khadgar contacted me.\n\nHe is investigating demonic influences to the north.\n\nBeing a human, the Frostwolves will not accept Khadgar without you there to vouch for him, nor will they accept a night elf such as myself.\n\nI will wait for you outside Throm'var in the Frostwind Crag.", completion = "Thank you for coming, {name}. The archmage and I are in need of your assistance.", objectives = "Meet Cordana Felsong outside of Thom'var in the Frostwind Crag.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
