quests[34215] = { id = 34215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Gorgrond Treasure 22" }
quests[34216] = { id = 34216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Safe Passage", description = "Being a human and a night elf, the archmage and I aren't likely to be well-received by the orcs of the Frostwolf clan.\n\nWe need you to make an introduction for us with the Throm'var farseer.\n\nThere is much to discuss. Shall I bring you up to speed on the way to the village?", progress = "You honor us with your presence.", completion = "Wolf-brother, already word has traveled to us of your actions at Wor'gol. You have the eternal respect of the Frostwolf.\n\nNow, who are these strangers that you have brought to us and what is this urgent matter?", objectives = "Hear Cordana Felsong's tale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34217] = { id = 34217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smash Blon'sky!", description = "Grulk not choose to be mutated. Grulk not monster like Blon'sky! Blon'sky evil... chose mutation for power!\n\nYou go to Grommar? Smash Blon'sky before he hurt innocents, make Grulk happy!", objectives = "Defeat Blon'sky.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34218] = { id = 34218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Gorgrond Treasure 23" }
