quests[34224] = { id = 34224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Creature Treasure: Bloodcleave" }
quests[34225] = { id = 34225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Creature Treasure: Iron Horde Slacker" }
quests[34227] = { id = 34227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Must Be Done", description = "I believe we have seen this demonic corruption your friends speak of.\n\nThe Mother of Wolves has not been herself lately. Now, her pack has her surrounded.\n\nThe wolves are protecting our hunters and will not let them near. They're not likely to stop you, though.\n\nIf the alpha mother is infected with this fel-energy, then she must be put down.\n\nYou would greatly honor the Frostwolves by returning with her corpse and giving it a proper burial.", progress = "Is it done? Does the Mother of Wolves finally rest in peace, {name}?", completion = "Unfortunate that there are those that would pervert such noble creatures.\n\nYou have honored their family once more, {name}. They will not forget.\n\nNow it is time to take the fight directly to the Shadow Council.", objectives = "Collect the Mother of Wolves' Remains and bury it at the graveyard outside of northern Throm'var.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34228] = { id = 34228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Clew of Worms", description = "While I was scouting, I noticed that most of Frostwind Crag is crawling with an odd species of worm.\n\nThe worst thing about them is that these things burrow under the ground and then spring on you from out of nowhere.\n\nI saw the worms attacking the frost wolves and other wildlife in the wastes. I'm certain the orcs would appreciate you helping out.", progress = "Watch your back out there. Those worms will attack when you're not looking.", completion = "We haven't seen these creatures here in a generation.\n\nTheir sudden appearance and the shaking of the ground are most definitely connected.", objectives = "Kill 15 Wastes Rockworms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34229] = { id = 34229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sleeper Has Awakened", description = "Something has awakened the great Shui Halad. She is causing the ground to quake.\n\n<The farseer makes a sign of warding in the air, and then continues.>\n\nPerhaps those who have disturbed the great worm are the same ones your friends are tracking down?\n\nEither way, Shui Halad must be put to eternal rest before her thrashing collapses all of the north into the ocean.", progress = "The ground yet rumbles, my friend. Do you need aid?", completion = "I've heard of these strange Pale orcs you saw. They sound like the Warsingers of Nagrand. But no, that cannot be....\n\nAs for the ogre, his name is Cho'gall. You should kill him if you get the chance. He brings nothing but destruction in his wake.", objectives = "Kill Shui Halad.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34230] = { id = 34230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eye Need That", description = "The Mother of Wolves was infected with demon magic. The Shadow Council must have hoped to spread the corruption to the other frost wolves and then to Throm'var.\n\nThe hunters are reporting they've seen glowing green eyes down in the Icescar Boneyard to the west. We both know what that means.\n\nI have an idea... we're going to use the Shadow Council's \"eyes\" against them to reveal their base. All we need is the lead warlock's All-Seeing Ring.", progress = "The All-Seeing Ring. Do you have it?", completion = "Yes, this will do nicely. Let's use the Shadow Council's magic against them.", objectives = "Collect the All-Seeing Ring from Ogzor the Necrothurge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34231] = { id = 34231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Giant Snake" }
quests[34232] = { id = 34232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Rook's Tacklebox" }
quests[34233] = { id = 34233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Jug of Aged Ironwine" }
quests[34234] = { id = 34234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Payback", description = "We thought we were safe behind Leafshadow's cloaking veil.\n\n<Vindicator Kaluud wipes the blood from his face.>\n\nSomeone told the Shadow Council's forces how to disable it. We were able to hold them off at first...\n\nMost of the town was slaughtered in the attack. Please, you must avenge our fallen. Rout these invaders out from Telmor forever!", completion = "Excellent. The shards are at last together!", objectives = "Rout 12 Shadow Council forces in Telmor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34235] = { id = 34235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Luminous Shell" }
