quests[34239] = { id = 34239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Treasure of Tuurem" }
quests[34240] = { id = 34240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scheduled Pickup", description = "You've proven yourself more than capable in battle, {name}. As you know, there may be Shadow Council forces anywhere around Auchindoun, including near Telmor.\n\nTuulani's powers as a soulpriest have not yet fully manifested; she isn't capable of protecting the shard alone. I need you to join her at Telmor to make sure the crystal makes it to Auchindoun safely.", completion = "It's not safe here. The Shadow Council has already taken the city!", objectives = "Speak to Soulbinder Tuulani outside Telmor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34241] = { id = 34241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Gorgrond Treasure 12" }
quests[34242] = { id = 34242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scheduled Pickup", description = "You've proven yourself more than capable in battle, {name}. There may be Shadow Council forces all around Auchindoun, including near Telmor.\n\nI want you to join Soulbinder Tuulani at Telmor to make sure the crystal makes it safely to Auchindoun. I know I can trust you to get it done.", completion = "It's not safe here. The Shadow Council has already taken the city!", objectives = "Speak to Soulbinder Tuulani outside Telmor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
