quests[34264] = { id = 34264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Collection of Coils", description = "None of the Thunderlord can escape my wrath! We need something to pull them out of the skies so that they can greet our blades.\n\nTheir wranglers should carry rope with them for handling their beasts. Slay them, if they have any coils in good condition bring them to me.", progress = "I'm growing tired of waiting, do you have anything to help our assault or not?", completion = "Rope? Do you expect me to tie a noose and ask the Thunderlords to go hang themselves?\n\nWait... that gives me an idea. Yea, I think I can make this work with the right materials.\n\nGood Job.", objectives = "Gather 5 Coils of Sturdy Rope from Thunderlord Wranglers in the Bones of Agurak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34267] = { id = 34267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grommar Forces" }
quests[34268] = { id = 34268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Task: Kill Wildlife" }
quests[34269] = { id = 34269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Task: Kill Wolf Boss" }
quests[34271] = { id = 34271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of Gordawg", description = "Looming monstrously between us and the inner chamber is the great fury we have sought to return to the Throne of Elements.\n\nGordawg stands before us enthralled; a slave to the pale and their mysterious master. My heart is heavy with grief to see such a great creature mindless and enslaved by evil.\n\nThere is no going back, in order to push forward you must go through Gordawg.\n\nIt pains me, but Gordawg must be slain.\n\nWhen the deed is done, we will return the fury's heart to the Throne of Elements.", progress = "What of Gordawg? Has the great fury been brought to rest?", completion = "Gordawg was a mighty ally. The elements will mourn the loss of the fury, but death was the only answer. Gordawg would not have wished to stay a slave to evil.\n\nThough Gordawg is no more, the heart of a fury is eternal and unbreakable. In time, this brightly glowing heart will take shape into a new earthen fury.\n\nSuch is the cycle of life upon the Elemental Plateau.", objectives = "Retrieve the Heart of the Fury.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34276] = { id = 34276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Rusted Lockbox" }
quests[34277] = { id = 34277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stop the Flow", description = "The Shadow Council down in the boneyard are going to have magic circles. It's not enough to simply kill them; we also have to eliminate their infernal devices.\n\nIf you destroy the circles, you'll stop the flow of demons they're summoning to inhabit the bones of the dead.", progress = "Were you able to destroy the Shadow Council's summoning circles?", completion = "We should have killed them all at the Dark Portal in the beginning and damn the consequences.", objectives = "Destroy 7 Summoning Circles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34278] = { id = 34278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desecration of the Dead", description = "These filthy warlocks are desecrating the dead in the boneyard!\n\n<The farseer trembles as he fails to keep his composure.>\n\nI WANT THEM DEAD!\n\nDestroy the necrophytes. Destroy their demonic abominations.", completion = "For what they've done, it is not enough.\n\n{name}, when you find their base, you salt the earth.", objectives = "Kill 15 Necrophytes and Fel Wolves.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34279] = { id = 34279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Am Blook", objectives = "Blook never beat before.\n\nBlook follow tiny person now, so Blook learn how to beat more people.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34280] = { id = 34280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All is Revealed", description = "Tell me when you're ready.\n\nWe'll invoke the power of the ring to summon one of their 'eyes.' Through it, we'll discover where the Shadow Council is located and what they're really up to.", completion = "Gul'dan is there! We must move quickly to capture him.", objectives = "Spy on the Shadow Council.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34281] = { id = 34281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of the Chains", description = "They roughed me up real good an' I have a splitting headache but I'll survive. I need to get out of this bit o' chain here though.\n\nCould ye get the key to it for me? A big ogre called Nub has it, he's over on the far side of the terrace.", progress = "Dun ye worry about me. I'll sit here an' nurse me wounds.", completion = "With that ball o' stone gone I be feelin' better already!", objectives = "Obtain the Bloodmaul Shackle Key and free Owynn Graddock.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34284] = { id = 34284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Campaign: The Search for Owynn Graddock", description = "Commander, I have bad news to report.\n\nAgent Graddock was out on assignment to keep an eye on the Bloodmaul and he missed his deadline to check back in.\n\nSomething's not right, {name}.\n\nIf Owynn was captured they may have locked him away with their slaves.\n\nHead over to Stonefury Cliffs and see if you can locate him.", completion = "Well I be a son of a gnome! Am I glad to see you! I was hoping fer a rescue but didn't expect da boss tae be here himself!", objectives = "Travel to the Stonefury Cliffs in Frostfire Ridge and search for Owynn Graddock.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34285] = { id = 34285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gearing Up", description = "When I was captured they took my gear and left me in rags. My mace is being used to crack stones and they're even using me best dagger as a dinner fork! I'd hate to know what happened to me armor but I hope its still usable.\n\nI'll need a wee bit to recover from me wounds and without my stuff I'm no help in a fight. Could ye go find my gear for me?\n\nLast I saw my armors in a chest next to that big tower south of here, my dagger was to the south west, and my mace over near that lava field to the west.", progress = "Just need a bit of a refresher, being beat up by ogres makes ye a little sore. Who knew?", completion = "Thank ye, looks like everything's still in good shape. Just give me a moment to put this on.", objectives = "Obtain Owynn's Dagger, Mace, and Gear.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
